def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = [int(x) for x in data[1 : 1 + n]]

    avg = sum(a) // n
    c = [0] * n
    for i in range(1, n):
        c[i] = c[i - 1] + (a[i - 1] - avg)

    c.sort()
    med = c[n // 2]
    ans = sum(abs(x - med) for x in c)
    sys.stdout.write(f"{ans}\n")


